# -*- coding: utf-8 -*-
"""Календарные поправки к дневному спросу: насколько конкретная дата отличается от нормы.

ЗАЧЕМ ОТДЕЛЬНЫЙ МОДУЛЬ, А НЕ КОНСТАНТА В ДВИЖКЕ
Прогноз строится по одноимённым дням недели: сегодняшняя пятница предсказывается по
четырём прошлым пятницам. Значит день недели УЖЕ учтён самим способом расчёта, и
добавлять к пятнице отдельный множитель «канун выходного» нельзя — это двойной счёт.
Именно так и было до 03.08.2026: `is_day_before_off` истинно для КАЖДОЙ пятницы, и
модель систематически завышала пятничную заявку на 4,5%. Проверено на 76 обычных
пятницах за 20 месяцев: их чистый индекс 0,999 — сверх дня недели там нет ничего.

Поэтому поправка здесь ОТНОСИТЕЛЬНАЯ: множитель целевого дня делится на средний
множитель тех исторических дней, по которым считался прогноз. Обычная пятница по
обычным пятницам даёт 1,00 и ничего не меняет. А 1 января по обычным четвергам даёт
0,19 — и только тогда поправка вступает в силу.

ОТКУДА ЧИСЛА
Дневной объём готовой еды по сопоставимым точкам (Точки 1 + Точка 2, только
у них есть полная история) делится на центрированную скользящую медиану за 29 дней —
это снимает и тренд, и сезонность. Затем снимается норма дня недели. Остаётся чистый
календарный эффект. Период: 01.12.2024–02.08.2026, 610 дней, по два наблюдения на дату.

Применяем множитель только там, где ОБА года согласны в направлении и эффект больше
10%. Где годы спорят (23 февраля: 1,23 и 0,91; 1 мая: 1,02 и 0,81) — оставляем 1,00.
Один разнобойный год — не знание, а шум, и лучше не трогать заявку вовсе.

Пересчитать таблицу: PYTHONUTF8=1 py prognoz/src/prognoz/external/calendar_effects.py
"""
import sys
from datetime import date
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3] / "analysis" / "etl"))
from prognoz.external import calendar_ru  # noqa: E402

# Конкретные даты (месяц-день) → множитель к норме своего дня недели.
# В скобках — наблюдения по годам, чтобы было видно, на чём число стоит.
FIXED_DATES = {
    (1, 1): (0.19, "1 января: город пустой, продажи падают впятеро (0,21 / 0,17)"),
    (1, 2): (0.38, "2 января (0,41 / 0,35)"),
    (1, 3): (0.63, "3 января (0,59 / 0,67)"),
    (1, 4): (0.79, "4 января (0,75 / 0,83)"),
    (1, 5): (0.64, "5 января (0,49 / 0,79)"),
    (1, 6): (0.96, "6 января (0,98 / 0,94)"),
    (1, 7): (0.83, "7 января, Рождество (0,82 / 0,84)"),
    (1, 8): (0.80, "8 января (0,70 / 0,89)"),
    (2, 14): (1.35, "14 февраля: одна из двух сильнейших дат года (1,27 / 1,43)"),
    (3, 8): (1.56, "8 марта: сильнейшая дата года (1,44 / 1,67)"),
    (5, 9): (0.83, "9 мая (0,74 / 0,91)"),
    (12, 31): (1.13, "31 декабря (1,17 / 1,08)"),
    (9, 1): (1.08, "1 сентября (1,12 по единственному году — осторожно)"),
}

# Даты, где два года противоречат друг другу: поправки нет, но и молчать о них нельзя.
DISPUTED = {
    (2, 23): "23 февраля (1,23 и 0,91 — годы спорят, поправку не применяем)",
    (5, 1): "1 мая (1,02 и 0,81 — годы спорят)",
    (6, 12): "12 июня (1,00 и 0,90 — эффекта нет)",
}

HOLIDAY_MULT = 0.94       # прочий нерабочий день, выпавший на пн–пт (17 набл.)
PRE_HOLIDAY_MULT = 1.07   # канун праздника, сокращённый день (7 набл.)

# Порог, за которым день считается календарно аномальным. Нужен движку: в такой день
# рамка «±15% к заявке сотрудника» должна отступить, иначе она вернёт заявку 1 января
# к обычному уровню и весь смысл поправки пропадёт — сотрудник в аномальный день
# ошибается сильнее модели, ограничивать модель его числом бессмысленно.
ANOMALY_THRESHOLD = 0.15


def day_factor(d: date) -> tuple[float, str]:
    """Множитель календаря для даты и человекочитаемая причина."""
    key = (d.month, d.day)
    if key in FIXED_DATES:
        mult, why = FIXED_DATES[key]
        return mult, why
    if key in DISPUTED:
        return 1.0, DISPUTED[key]

    cal = {r.date: r for r in calendar_ru.load().itertuples()}
    row = cal.get(d)
    if row is None:
        return 1.0, ""
    if bool(getattr(row, "is_preholiday", False)):
        return PRE_HOLIDAY_MULT, "канун праздника (сокращённый день)"
    # Нерабочий день в пн–пт — это праздник. Суббота и воскресенье тоже помечены
    # календарём как нерабочие, но они обычные: их вес уже сидит в дне недели.
    if bool(getattr(row, "is_dayoff", False)) and d.weekday() < 5:
        return HOLIDAY_MULT, "нерабочий праздничный день"
    return 1.0, ""


def relative_factor(target: date, history: list[date]) -> tuple[float, str]:
    """Поправка целевого дня ОТНОСИТЕЛЬНО дней, по которым построен прогноз.

    Возвращает (множитель, пояснение). Множитель 1,0 означает «календарь ничего
    не меняет»: так и должно быть в подавляющем большинстве дней.
    """
    f_t, why = day_factor(target)
    if not history:
        return f_t, why
    hist = [day_factor(h)[0] for h in history]
    f_h = sum(hist) / len(hist)
    if f_h <= 0:
        return f_t, why
    rel = f_t / f_h
    if abs(rel - 1) < 0.01:
        # Поправки нет — но если дата сама по себе особая, причину назвать обязаны.
        # В файле заявки это отдельная строка: «про 23 февраля система знает и
        # осознанно не трогает» читается иначе, чем молчание.
        return 1.0, why
    if not why:
        # целевой день обычный, а вот в истории попался праздник — тоже поправка
        why = "в истории одноимённых дней был особый день, поправка на это"
    return rel, why


def is_anomalous(d: date) -> bool:
    """Достаточно ли день необычен, чтобы отпустить предохранители движка."""
    return abs(day_factor(d)[0] - 1) >= ANOMALY_THRESHOLD


def main():
    from datetime import timedelta
    print("Календарные поправки, ближайший год:\n")
    d = date.today()
    shown = 0
    while d < date.today() + timedelta(days=400) and shown < 30:
        f, why = day_factor(d)
        if abs(f - 1) > 0.01 or why:
            flag = " ⚠ аномалия" if is_anomalous(d) else ""
            print(f"  {d:%d.%m.%Y} ({'пн вт ср чт пт сб вс'.split()[d.weekday()]}) "
                  f"×{f:.2f}  {why}{flag}")
            shown += 1
        d += timedelta(days=1)
    return 0


if __name__ == "__main__":
    sys.exit(main())
